contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint _value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint cBal0 = address(c).balance;
        uint myBal0 = address(this).balance;
        bool reverted;
        c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted ? (address(c).balance == cBal0 && address(this).balance == myBal0)
                        : (address(this).balance == myBal0 + _value && address(c).balance + _value == cBal0));
    }
    receive() external payable {}
}

